mapper.select:
select
a.union_id,
a.plan_id,
a.area_id,
a.name,
a.type,
a.if_run,
a.robot_id,
a.date_type,
a.remark1,
a.remark2,
a.remark3,
a.task_type,
a.start_time,
a.create_time
from t_union_task a
where 1 = 1
 and a.union_id = #{unionId, jdbcType=VARCHAR}
 and a.plan_id = #{planId, jdbcType=BIGINT}
 and a.area_id = #{areaId, jdbcType=VARCHAR}
 and a.name = #{name, jdbcType=VARCHAR}
 and a.type = #{type, jdbcType=INTEGER}
 and a.if_run = #{ifRun, jdbcType=INTEGER}
 and a.robot_id = #{robotId, jdbcType=BIGINT}
 and a.date_type = #{dateType, jdbcType=INTEGER}
 and a.remark1 = #{remark1, jdbcType=INTEGER}
 and a.remark2 = #{remark2, jdbcType=INTEGER}
 and a.remark3 = #{remark3, jdbcType=VARCHAR}
 and a.task_type = #{taskType, jdbcType=INTEGER}
 and a.start_time = #{startTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

